#!/bin/bash
# DroidDeck-Proton source preparation.
# Runs GE-Proton's own patches/protonprep-valve-staging.sh minus its "(2) WINE PATCHING" section.
# The wine submodule (The412Banner/proton-wine, banner-proton/11.7) already carries that section as
# tier 2 commits, generated by running the same section unmodified (see verify-tier2.sh).
set -euo pipefail
cd "$(dirname "$0")/.."

GE_PREP=patches/protonprep-valve-staging.sh
grep -q '^### (2) WINE PATCHING ###$' "$GE_PREP"
grep -q '^### END WINE PATCHING ###$' "$GE_PREP"

awk '
/^### \(2\) WINE PATCHING ###$/ { skip=1 }
!skip { print }
/^### END WINE PATCHING ###$/ { skip=0 }
' "$GE_PREP" > /tmp/banner-proton-prep.sh

# GE's script has no "set -e"; GE CI also tolerates a non-zero exit. Fail on any patch error instead.
sed -i 's/^    patch -Np1 < "\$patch_path"$/    patch -Np1 < "$patch_path" || { echo "PATCH FAILED: $patch_path" >\&2; exit 1; }/' /tmp/banner-proton-prep.sh
grep -q 'PATCH FAILED' /tmp/banner-proton-prep.sh
bash -e /tmp/banner-proton-prep.sh

# The wine tree must be the pinned Banner-Proton branch commit, untouched.
test -z "$(git -C wine status --porcelain)"
echo "wine: $(git -C wine log -1 --format='%H %s')"
